class BowlingGame:
    def __init__(self):
        self.rolls = []
        self.frame = 0
        self.rolls_in_frame = 0
        self.game_over = False

    def roll(self, pins):
        if self.game_over:
            raise Exception("Cannot roll after the game is complete.")
        if not 0 <= pins <= 10:
            raise Exception("A roll must knock down between 0 and 10 pins.")

        if self.frame < 9:
            self._roll_regular_frame(pins)
        else:
            self._roll_tenth_frame(pins)

    def _roll_regular_frame(self, pins):
        if self.rolls_in_frame == 0:
            self.rolls.append(pins)
            if pins == 10:
                self._complete_frame()
            else:
                self.rolls_in_frame = 1
        else:
            if self.rolls[-1] + pins > 10:
                raise Exception(
                    "Two rolls in a frame cannot score more than 10 points."
                )
            self.rolls.append(pins)
            self._complete_frame()

    def _roll_tenth_frame(self, pins):
        if self.rolls_in_frame == 0:
            self.rolls.append(pins)
            self.rolls_in_frame = 1
        elif self.rolls_in_frame == 1:
            first = self.rolls[-1]
            if first != 10 and first + pins > 10:
                raise Exception(
                    "Two rolls in a frame cannot score more than 10 points."
                )
            self.rolls.append(pins)
            if first == 10 or first + pins == 10:
                self.rolls_in_frame = 2
            else:
                self._complete_frame()
        else:
            first, second = self.rolls[-2], self.rolls[-1]
            if first == 10 and second != 10 and second + pins > 10:
                raise Exception(
                    "Two rolls in a frame cannot score more than 10 points."
                )
            self.rolls.append(pins)
            self._complete_frame()

    def _complete_frame(self):
        self.frame += 1
        self.rolls_in_frame = 0
        if self.frame == 10:
            self.game_over = True

    def score(self):
        if not self.game_over:
            raise Exception("Cannot score an incomplete game.")
        total = 0
        i = 0
        for _ in range(10):
            if self.rolls[i] == 10:
                total += 10 + self.rolls[i + 1] + self.rolls[i + 2]
                i += 1
            elif self.rolls[i] + self.rolls[i + 1] == 10:
                total += 10 + self.rolls[i + 2]
                i += 2
            else:
                total += self.rolls[i] + self.rolls[i + 1]
                i += 2
        return total

